from helpers import *
LU="Lucent's General Knowledge"; NG="NCERT Class 6-8 Social Science (Geography) and Class 11, Fundamentals of Physical Geography"
W=week(HRS,{"quant":["Speed & Distance","Boats & Streams"],"reasoning":["Syllogism","Venn Diagrams"],"english":["Idioms","One Word"],"ga":["Geography"]},
unit("Quant: Speed, trains, boats and streams",[
 part("Part 1: Speed, time, distance",
  [rd(RSA,"Chapter 'Time and Distance'"),rd(KM,"Chapter 'Time and Distance': first 10 solved questions")],
  ["Distance = speed × time. km/h to m/s: multiply by 5/18. m/s to km/h: multiply by 18/5.",
   "Same distance, speeds in ratio a : b means times in ratio b : a.",
   "Average speed over equal distances at speeds x and y = 2xy/(x + y). It is not the simple average.",
   "Relative speed: same direction subtract, opposite directions add."],
  [ex("Convert 72 km/h to m/s.","20 m/s","72 × 5/18 = 20."),
   ex("Go at 40 km/h and return at 60 km/h. Average speed?","48 km/h","2 × 40 × 60/100 = 48."),
   ex("A man covers 120 km in 3 h. Time for 200 km at the same speed?","5 hours","Speed 40 km/h, 200/40 = 5."),
   ex("Two cars 300 km apart move towards each other at 40 and 60 km/h. When do they meet?","3 hours","300/100 = 3.")],
  [sv("Book practice, 60 minutes max","RSA 'Time and Distance': first 40 questions."),sv("Previous-year questions","KM: 25 questions."),sv("App drill",None,dr("quant","Speed & Distance",20,15))]),
 part("Part 2: Trains",
  [rd(RSA,"Chapter 'Problems on Trains'"),rd(KM,"Chapter 'Trains': first 10 solved questions")],
  ["Train passing a pole or a man: distance = length of train.",
   "Train passing a platform or bridge: distance = train length + platform length.",
   "Two trains in opposite directions: relative speed = sum; same direction: difference. Distance = sum of both lengths.",
   "Always convert km/h to m/s first when lengths are in metres."],
  [ex("A 150 m train at 54 km/h crosses a pole. Time?","10 s","54 km/h = 15 m/s; 150/15 = 10."),
   ex("A 200 m train at 72 km/h crosses a 300 m platform. Time?","25 s","500/20 = 25."),
   ex("Trains 100 m and 120 m at 60 and 40 km/h run in opposite directions. Time to cross?","7.92 s","220 m ÷ (100 × 5/18 = 27.78 m/s) = 7.92 s."),
   ex("Same trains, same direction. Time to cross?","39.6 s","220 ÷ (20 × 5/18 = 5.56) = 39.6 s.")],
  [sv("Book practice, 60 minutes max","RSA 'Problems on Trains': first 40 questions."),sv("Previous-year questions","KM 'Trains': 20 questions."),sv("App drill",None,dr("quant","Speed & Distance",20,15,"85%"))]),
 part("Part 3: Boats and streams",
  [rd(RSA,"Chapter 'Boats and Streams'"),rd(KM,"Chapter 'Boats and Streams': first 10 solved questions")],
  ["Downstream speed D = u + v. Upstream speed U = u − v (u = boat in still water, v = stream).",
   "u = (D + U)/2 and v = (D − U)/2.",
   "Time for a round trip over distance d: d/(u + v) + d/(u − v).",
   "Same drill as trains: draw the two speeds first, then use distance/speed."],
  [ex("Boat 10 km/h in still water, stream 2 km/h. Downstream speed?","12 km/h"),
   ex("Downstream 15 km/h, upstream 9 km/h. Boat speed and stream speed?","12 and 3 km/h","(15 + 9)/2 = 12; (15 − 9)/2 = 3."),
   ex("A boat goes 24 km downstream in 2 h and returns in 3 h. Stream speed?","2 km/h","D = 12, U = 8, v = 2.")],
  [sv("Book practice, 60 minutes max","RSA 'Boats and Streams': first 30 questions."),sv("Previous-year questions","KM: 15 questions."),sv("App drill",None,dr("quant","Boats & Streams",15,12))])]),
unit("Reasoning: Syllogism and Venn diagrams",[
 part("Part 1: Syllogism basics",
  [rd(RV,"Chapter 'Syllogism'"),rd(KR,"Chapter 'Syllogism': first 15 questions")],
  ["Four statement types: All A are B (universal positive), No A is B (universal negative), Some A are B (particular positive), Some A are not B (particular negative).",
   "All + All → All. All + No → No. Some + All → Some. No + All → Some not.",
   "Draw Venn circles for every statement. A conclusion is correct only if it is true in every diagram.",
   "'Some' always converts to 'Some' (Some A are B means Some B are A). 'No' converts to 'No'."],
  [ex("All cats are dogs. All dogs are rats. Conclusion: All cats are rats?","True","All + All → All."),
   ex("Some pens are books. All books are tables. Conclusion: Some pens are tables?","True","Some + All → Some."),
   ex("No bag is a box. All boxes are boats. Conclusion: No bag is a boat?","Not necessarily","No + All → only 'Some boats are not bags' is certain.")],
  [sv("Book practice, 40 minutes","RV 'Syllogism': 30 questions."),sv("App drill",None,dr("reasoning","Syllogism",15,10))]),
 part("Part 2: Either-or and possibility",
  [rd(RV,"Syllogism: 'Either-Or' and 'Possibility' sections"),rd(KR,"Syllogism: questions 16 to 35")],
  ["If two conclusions involve the same subject and predicate and form a complementary pair (Some A are B and No A is B, or All A are B and Some A are not B), the answer is 'either-or'.",
   "A possibility conclusion ('Some A can be B') is true if no statement rules it out in some diagram.",
   "Check both conclusions separately first, then look for either-or."],
  [ex("Statements: Some roses are red. Conclusions: (I) All roses are red. (II) Some roses are not red.","Either I or II","They are complementary but neither is certain alone.")],
  [sv("Book practice, 40 minutes","RV: either-or and possibility exercises."),sv("App drill",None,dr("reasoning","Syllogism",15,10,"85%"))]),
 part("Part 3: Venn diagrams",
  [rd(RV,"Chapter 'Venn Diagrams'"),rd(KR,"Chapter 'Venn Diagram': first 15 questions")],
  ["Pick a circle for each group. Circles inside means 'is a subset of' (Dogs inside Animals). Overlapping means 'some may be both'. Separate means 'no overlap'.",
   "Three-group diagrams: ask whether each pair overlaps. Example: Doctors, Teachers, Males (all three overlap partly); Mother, Sister, Woman (Woman contains both; Mother and Sister can overlap or not).",
   "Count questions: total = A + B − both. Fill from the centre outward."],
  [ex("Which diagram fits Pen, Pencil, Stationery?","Two separate circles inside a larger one","Pen and Pencil are different but both are stationery."),
   ex("In a class 30 play cricket, 20 play tennis, 10 play both. How many play at least one?","40","30 + 20 − 10 = 40.")],
  [sv("Book practice, 40 minutes","RV 'Venn Diagrams': 25 questions."),sv("App drill",None,dr("reasoning","Venn Diagrams",6,6))])]),
unit("English: Idioms and one-word substitution",[
 part("Part 1: Idioms and phrases A to H",
  [rd(SB,"Chapter 'Idioms and Phrases': A to H"),rd(WM,"Idioms section")],
  ["Learn 10 idioms a day with a one-line story each. Say the meaning aloud, then use it in a sentence.",
   "Examples: 'A blessing in disguise' = a good thing that seemed bad at first. 'At daggers drawn' = bitter enemies. 'Bolt from the blue' = sudden shock. 'Cry over spilt milk' = regret the past. 'Beat about the bush' = avoid the point.",
   "Revise yesterday's 10 before learning new ones."],
  [ex("'A bolt from the blue' means","A sudden unexpected event"),ex("'At daggers drawn' means","Bitterly hostile"),ex("'Beat about the bush' means","Avoid the main point")],
  [sv("Learn","SB: 30 idioms from A to H into a notebook."),sv("App drill",None,dr("english","Idioms",10,8))]),
 part("Part 2: Idioms I to Z",
  [rd(SB,"Chapter 'Idioms and Phrases': I to Z"),rd(WM,"Idioms: remaining section")],
  ["Examples: 'Once in a blue moon' = very rarely. 'Piece of cake' = very easy. 'Spill the beans' = reveal a secret. 'The last straw' = final provocation. 'Wild goose chase' = futile search. 'Under the weather' = unwell.",
   "Make flashcards: idiom on one side, meaning on the other."],
  [ex("'Once in a blue moon' means","Very rarely"),ex("'Spill the beans' means","Reveal a secret"),ex("'Under the weather' means","Feeling ill")],
  [sv("Learn","SB: 30 idioms from I to Z into a notebook."),sv("App drill",None,dr("english","Idioms",10,8,"85%"))]),
 part("Part 3: One-word substitution",
  [rd(SB,"Chapter 'One Word Substitution'"),rd(NL,"Chapters 1 to 3 for root words")],
  ["Learn by category. People: Philanthropist (loves mankind), Misanthrope (hates mankind), Atheist (no belief in God), Egoist (self-centred), Pedestrian (walks), Optimist.",
   "Fear: Claustrophobia (closed spaces), Acrophobia (heights), Hydrophobia (water). Rule: Autocracy (rule by one), Democracy (by the people), Aristocracy (by nobles), Bureaucracy (officials).",
   "Others: Omnipotent (all-powerful), Omniscient (all-knowing), Bibliophile (book lover), Somniloquist (talks in sleep), Monolingual (one language)."],
  [ex("One who loves mankind","Philanthropist"),ex("Fear of closed spaces","Claustrophobia"),ex("Government by nobles","Aristocracy")],
  [sv("Learn","SB: 40 one-word substitutions into a notebook."),sv("App drill",None,dr("english","One Word",10,8))])]),
unit("GA: Indian geography",[
 part("Part 1: Physical features and mountains",
  [rd(NG,"NCERT Class 11, Fundamentals of Physical Geography, Chapters 1 to 5"),rd(LU,"Geography: India, physical features")],
  ["Himalayas: Himadri (Greater), Himachal (Lesser), Shivalik (Outer). Kanchenjunga (8,586 m) is the highest peak in India; Mount Everest is in Nepal.",
   "Peninsular plateau: Deccan. Western Ghats (Sahyadri) are higher than the Eastern Ghats. Anamudi (2,695 m) is the highest peak of South India; Doddabetta is in the Nilgiris.",
   "Thar Desert is in Rajasthan. Sunderbans delta (Ganga-Brahmaputra) is the largest delta in the world.",
   "Standard meridian: 82°30′E (passes near Mirzapur). The Tropic of Cancer passes through 8 states: Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura, Mizoram."],
  [ex("Highest peak in India?","Kanchenjunga"),ex("Tropic of Cancer passes through how many states?","8"),ex("Highest peak of South India?","Anamudi")],
  [sv("Map work","Draw India's outline and mark 5 ranges, 5 plateaus and the 8 states on the Tropic of Cancer."),sv("App drill",None,dr("ga","Geography",15,10))]),
 part("Part 2: Rivers and lakes",
  [rd(NG,"NCERT Class 9, Contemporary India I, Chapter 'Drainage'"),rd(LU,"Geography: Rivers, lakes")],
  ["Himalayan rivers are perennial: Ganga (2,525 km, from Gangotri as Bhagirathi), Yamuna, Brahmaputra (Tsangpo in Tibet, Siang in Arunachal), Indus.",
   "Peninsular rivers are seasonal: Godavari (longest peninsular river, called 'Dakshin Ganga'), Krishna, Kaveri, Mahanadi. Narmada and Tapi flow west into the Arabian Sea through rift valleys.",
   "Lakes: Chilika (largest coastal lagoon, Odisha), Wular (largest freshwater lake, J&K), Sambhar (largest inland salt lake, Rajasthan), Loktak (Manipur), Pulicat (Andhra-Tamil Nadu border).",
   "Confluences: Devprayag (Alaknanda and Bhagirathi form the Ganga), Prayagraj (Ganga, Yamuna, and the hidden Saraswati)."],
  [ex("Longest peninsular river?","Godavari"),ex("Largest freshwater lake in India?","Wular Lake"),ex("Largest coastal lagoon?","Chilika")],
  [sv("Map work","Mark 8 rivers with their source and the sea they fall into."),sv("App drill",None,dr("ga","Geography",15,10,"85%"))]),
 part("Part 3: Soils, climate and agriculture",
  [rd(NG,"NCERT Class 9, Contemporary India I, Chapters on climate, soils, agriculture"),rd(LU,"Geography: Soils, crops")],
  ["Soils: Alluvial (most widespread, rice, wheat, sugarcane), Black or regur (cotton, from basalt), Red (iron oxide), Laterite (heavy rain, cashew), Desert (Rajasthan).",
   "Monsoon arrives at Kerala around 1 June. Rainfall is highest at Mawsynram (Meghalaya). Rabi crops (wheat, mustard, gram) are sown in winter; Kharif crops (rice, maize, cotton, jowar) in the monsoon; Zaid in summer.",
   "Top producers: Rice (West Bengal, UP), Wheat (UP), Cotton (Gujarat, Maharashtra), Tea (Assam), Coffee (Karnataka), Sugarcane (UP)."],
  [ex("Which soil suits cotton?","Black soil"),ex("Where is the highest rainfall in India?","Mawsynram"),ex("Which crop is a Rabi crop: rice or wheat?","Wheat")],
  [sv("Make a table","Soil / Where found / Crop, 5 rows."),sv("App drill",None,dr("ga","Geography",15,10))])])
)
add_week('p1','p1-w5',W)
